"""Generate the browser snippets used to schedule one approved calendar post on X (paste text, alt texts, schedule)."""
import json, sys
post_id = sys.argv[1]
which = sys.argv[2]
data = {p['id']: p for p in json.load(open('/Users/medikamedika/KOMET/marketing/out/posts/schedule-batch1.json'))}
p = data[post_id]
hh, mm = map(int, p['slot'].split(':'))
ampm = 'pm' if hh >= 12 else 'am'
h12 = hh - 12 if hh > 12 else (12 if hh == 0 else hh)
label = f"{h12}:{mm:02d} {ampm.upper()}"
T = json.dumps(p['text'], ensure_ascii=False)
A = json.dumps(p['alts'], ensure_ascii=False)
first = json.dumps(p['text'].split('\n')[0][:30], ensure_ascii=False)
if which == 'paste':
    print(f"""const sleep=ms=>new Promise(r=>setTimeout(r,ms)); let ed=null; for(let i=0;i<40&&!ed;i++){{ ed=[...document.querySelectorAll('[role="dialog"] [data-testid="tweetTextarea_0"]')].pop(); if(!ed) await sleep(250); }} if(!ed) throw new Error('composer not found'); if(ed.innerText.trim().length) throw new Error('composer not empty: '+ed.innerText.slice(0,40)); ed.focus(); const text={T}; const dt=new DataTransfer(); dt.setData('text/plain',text); ed.dispatchEvent(new ClipboardEvent('paste',{{clipboardData:dt,bubbles:true,cancelable:true}})); await sleep(900); const norm=s=>s.replace(/\\s+/g,' ').trim(); ({{ok: norm(ed.innerText)===norm(text)}})""")
elif which == 'alts':
    print(f"""const sleep=ms=>new Promise(r=>setTimeout(r,ms)); async function waitFor(fn,t=12000){{const s=Date.now();while(Date.now()-s<t){{const v=fn();if(v)return v;await sleep(200);}}return null;}} const ALTS={A}; const ed=[...document.querySelectorAll('[role="dialog"] [data-testid="tweetTextarea_0"]')].find(e=>e.innerText.trim().length); const dlg=ed.closest('[role="dialog"]'); const edit=await waitFor(()=>{{const b=[...dlg.querySelectorAll('[aria-label="Edit media"], button')].filter(x=>x.getAttribute('aria-label')==='Edit media'||x.innerText.trim()==='Edit'); return b.length>=ALTS.length?b[0]:null;}},20000); if(!edit) throw new Error('media not ready'); edit.click(); const lens=[]; for(let i=0;i<ALTS.length;i++){{ const tab=await waitFor(()=>[...document.querySelectorAll('[role="tab"]')].find(t=>t.getAttribute('aria-label')==='Edit image description')); if(!tab) throw new Error('no ALT tab at '+i); tab.click(); await sleep(600); const ta=await waitFor(()=>document.querySelector('textarea')); Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype,'value').set.call(ta,ALTS[i]); ta.dispatchEvent(new Event('input',{{bubbles:true}})); await sleep(350); lens.push(ta.value.length); if(i<ALTS.length-1){{ const next=[...document.querySelectorAll('button')].find(b=>/^next$/i.test((b.getAttribute('aria-label')||'').trim())); if(!next) throw new Error('no next: '+[...document.querySelectorAll('[role="dialog"] button[aria-label]')].map(b=>b.getAttribute('aria-label')).join(',')); next.click(); await sleep(800); }} }} const save=[...document.querySelectorAll('button')].find(b=>b.innerText.trim()==='Save'); save.click(); await sleep(1200); ({{lens, expected: ALTS.map(a=>a.length)}})""")
elif which == 'schedule':
    print(f"""const sleep=ms=>new Promise(r=>setTimeout(r,ms)); const ed=[...document.querySelectorAll('[role="dialog"] [data-testid="tweetTextarea_0"]')].find(e=>e.innerText.trim().length); const dlg=ed.closest('[role="dialog"]'); const imgs=dlg.querySelectorAll('[aria-label="Edit media"]').length; const sb=dlg.querySelector('[aria-label="Schedule post"]'); if(!sb) throw new Error('no schedule button'); sb.click(); let sel=[]; for(let i=0;i<50&&sel.length<6;i++){{ await sleep(200); sel=[...document.querySelectorAll('select')]; }} const by=l=>sel.find(s=>document.getElementById(s.getAttribute('aria-labelledby'))?.innerText===l); const setv=(s,v)=>{{Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype,'value').set.call(s,v); s.dispatchEvent(new Event('change',{{bubbles:true}}));}}; setv(by('Month'),'10'); setv(by('Day'),'12'); setv(by('Year'),'2026'); setv(by('Hour'),'{h12}'); setv(by('Minute'),'{mm}'); setv(by('AM/PM'),'{ampm}'); await sleep(500); const will=[...document.querySelectorAll('span,div')].map(e=>(e.innerText||'').trim()).find(t=>/^Will send on .*(AM|PM)$/.test(t)); if(!/Oct 12, 2026 at {label}$/.test(will||'')) throw new Error('wrong time '+will); const confirm=[...document.querySelectorAll('button')].find(b=>b.innerText.trim()==='Confirm'); confirm.click(); let btn=null; for(let i=0;i<60&&!btn;i++){{ await sleep(250); btn=[...document.querySelectorAll('[data-testid="tweetButton"]')].find(b=>b.innerText.trim()==='Schedule'); }} if(!btn) throw new Error('no Schedule button'); const d2=btn.closest('[role="dialog"]'); const e2=d2.querySelector('[data-testid="tweetTextarea_0"]'); if(!e2.innerText.trim().startsWith({first})) throw new Error('text mismatch'); btn.click(); let toast=''; for(let i=0;i<30&&!toast;i++){{ await sleep(300); toast=[...document.querySelectorAll('[role="alert"],[data-testid="toast"]')].map(e=>e.innerText).join(' | '); }} ({{imgs, will, toast}})""")
